// CraeteRider is the resolver for the craeteRider field.
func (r *mutationResolver) CraeteRider(ctx context.Context, dpfile *graphql.Upload, idCardfiles []*graphql.Upload, input *model.RiderInput) (*model.Rider, error) {
	// Clean phone number
	cleanedNumber := helper.CleanPhoneNumber(input.Number)

	// Check if rider with the same name, email, or number already exists
	err := helper.CheckAllDuplicateRecords(r.DB, &model.Rider{}, input.Name, input.Email, cleanedNumber)
	if err != nil {
		return nil, err
	}

	// Create a new rider instance
	rider := model.Rider{
		Name:         input.Name,
		Email:        input.Email,
		Type:         input.Type,
		Number:       cleanedNumber,
		Location:     input.Location,
		State:        input.State,
		Availability: input.Availability,
		Experience:   input.Experience,
		Coordinates:  helper.ConvertToFloat64Array(input.Coordinates),
		H3Indexes:    helper.ConvertToStringArray(input.H3Indexes),
	}

	// Hash password if provided
	if input.Password != nil {
		hashedPassword, err := bcrypt.GenerateFromPassword([]byte(*input.Password), bcrypt.DefaultCost)
		if err != nil {
			return nil, fmt.Errorf("failed to hash password: %w", err)
		}
		hashedPasswordStr := string(hashedPassword)
		rider.Password = &hashedPasswordStr
	}

	// Save the rider to database
	if err := r.DB.Create(&rider).Error; err != nil {
		return nil, fmt.Errorf("failed to create rider: %w", err)
	}
	bucketName := fmt.Sprintf("rider-%s-bucket", rider.ID.String())

	// Use the stable UUID as part of the bucket name

	log.Printf("Stable bucket name: %s", bucketName)

	// Ensure the bucket exists
	if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
		return nil, err
	}

	if dpfile != nil {

		// Upload the file
		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "dpfile", dpfile)
		if err != nil {
			return nil, fmt.Errorf("failed to upload dpfile %s: %v", dpfile.Filename, err)
		}

		// Save the uploaded file URL
		rider.Dpfile = &fileURL
	}
	var idCardsURLs []string

	for _, file := range idCardfiles {
		// log.Printf("Uploading file: %s", file.Filename)

		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "idCards", file)
		if err != nil {
			return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
		}
		idCardsURLs = append(idCardsURLs, fileURL)
	}
	// Save the uploaded file URL
	rider.IDCard = idCardsURLs
	r.DB.Save(&rider)

	return &rider, nil
}

